// 卫生、疾病、精神危机的状态推进。数值全部走 rules.js，这里只负责把它们接到角色身上。
import { getData } from './data.js';
import { rng } from './rng.js';
import { clamp, diseaseStep, diseaseStage, hygieneRisk, mindStep } from './rules.js';

export const DISEASES = {
  gut: { name: '肠胃不适', basic: ['rehydration'], matching: ['care_course'], support: 'rehydration', hint: '补液用品减轻附加消耗；诊所计划用品才能压病情' },
  skin: { name: '卫生相关皮肤感染', basic: ['cleaning_care'], matching: ['cleaning_care', 'care_course'], hint: '清洁护理包可护理；保持卫生≥40，否则每回合多+2' },
  wound: { name: '未护理伤口感染', basic: ['bandage', 'cleaning_care'], matching: ['bandage', 'cleaning_care', 'care_course'], hint: '绷带只对重度以下有效；重度需诊所计划' },
  chill: { name: '受寒虚弱', basic: [], matching: [], hint: '暖处休整与干燥床位能压下去；症状缓解包减轻惩罚' },
};

export function addDisease(state, actorId, kind, severity, cause, events) {
  const p = state.actors[actorId];
  if (p.diseases.some((d) => d.kind === kind)) return null;
  if (p.diseases.length >= 2) return null;
  state.diseaseSeq = (state.diseaseSeq || 0) + 1;
  const d = { uid: 'd' + state.diseaseSeq, kind, severity: clamp(severity, 1, 100), known: kind === 'chill' || kind === 'wound', plan: false, startDay: state.day, cause, reliefUntil: 0 };
  p.diseases.push(d);
  events.push(`${state.names[actorId]}${d.known ? '出现' + DISEASES[kind].name : '身体不对劲（' + cause + '），需要诊所评估'}。`);
  return d;
}

// 某件用品对某病是否算“匹配护理”。
export function careMatches(disease, itemId) {
  const def = DISEASES[disease.kind];
  if (itemId === 'care_course') return disease.plan && disease.known;
  if (disease.kind === 'wound' && itemId === 'bandage') return disease.severity < 60;
  return def.basic.includes(itemId) && def.matching.includes(itemId);
}

// 一个行动回合的病情推进。flags: dirty, rested, safeSleep, caredIds(set of disease uid)
export function progressDiseases(state, actorId, flags, events) {
  const p = state.actors[actorId];
  const rules = getData().rules;
  let total = 0;
  for (const d of p.diseases) {
    const matching = flags.cared?.has(d.uid) || (d.kind === 'chill' && flags.rested && flags.warmPlace);
    const r = diseaseStep(d.severity, p.health, { dirty: flags.dirty && d.kind !== 'chill', matchingCare: matching, rest: flags.rested, safeSleep: flags.safeSleep }, rules);
    let damage = r.damage;
    if (d.supportUntil && state.turn <= d.supportUntil) damage = Math.max(0, damage - 3);
    if (d.reliefUntil && state.turn <= d.reliefUntil) damage = Math.max(0, damage - 3);
    d.severity = r.severity;
    p.health = clamp(p.health - damage);
    total += damage;
    if (d.severity <= 0) events.push(`${state.names[actorId]}的${DISEASES[d.kind].name}已缓解。`);
  }
  p.diseases = p.diseases.filter((d) => d.severity > 0);
  return total;
}

// 精神：愿望压力与恢复量进危机链。
export function mentalTick(state, actorId, pressure, recovery, events) {
  const p = state.actors[actorId];
  const rules = getData().rules;
  const wasCrisis = p.crisis;
  const r = mindStep({ mind: p.mind, zeroTurns: p.zeroTurns, crisis: p.crisis, health: p.health }, pressure, recovery, rules);
  p.mind = r.mind;
  p.zeroTurns = r.zeroTurns;
  p.crisis = r.crisis;
  p.health = r.health;
  if (r.crisis && !wasCrisis) events.push(`${state.names[actorId]}精神崩溃：连续${rules.mentalCrisis.consecutiveTurns}回合精神归零，每回合健康-${rules.mentalCrisis.zeroMindHealthDamage}，直到精神回到${rules.mentalCrisis.recoveryMindThreshold}以上。`);
  else if (!r.crisis && wasCrisis) events.push(`${state.names[actorId]}走出了崩溃。`);
  else if (!r.crisis && r.zeroTurns > 0) events.push(`${state.names[actorId]}精神已连续${r.zeroTurns}回合为0；再${rules.mentalCrisis.consecutiveTurns - r.zeroTurns}回合将崩溃并损失健康。`);
  return r.damage;
}

// 夜间每人一次暴露检定，以及极端污秽保底。
export function nightExposure(state, actorId, events) {
  const p = state.actors[actorId];
  const rules = getData().rules;
  const flags = { dirtyFood: p.exposure.dirtyFood, openWound: p.exposure.wound && !p.exposure.woundCovered, care: p.exposure.cared };
  const risk = hygieneRisk(p.hygiene, flags, rules);
  const r = rng(state.seed, 'expo:' + state.day + ':' + actorId);
  let got = null;
  if (p.diseases.length < 2 && r < risk) {
    const kind = flags.openWound ? 'wound' : flags.dirtyFood ? 'gut' : p.hygiene < 40 ? 'skin' : r < risk / 2 ? 'gut' : 'skin';
    got = addDisease(state, actorId, kind, 12 + Math.floor(r * 100) % 10, kind === 'wound' ? '伤口没有处理' : kind === 'gut' ? '吃了不干净的东西' : '长期不洗', events);
    if (got) p.dirtyStreak = 0;
  }
  if (p.hygiene <= rules.hygiene.criticalDirtyThreshold) p.dirtyStreak += 1;
  else p.dirtyStreak = 0;
  if (!got && p.dirtyStreak >= rules.hygiene.criticalDirtyConsecutiveTurns && !p.diseases.some((d) => d.kind === 'skin')) {
    addDisease(state, actorId, 'skin', 20, '极端污秽持续', events);
    p.dirtyStreak = 0;
  }
  p.exposure = { dirtyFood: false, wound: p.exposure.wound, woundCovered: false, cared: false };
  return risk;
}

export function diseaseLabel(d) {
  const stage = diseaseStage(d.severity, getData().rules);
  return `${DISEASES[d.kind].name}${d.known ? '' : '（待诊断）'} ${stage.label} ${d.severity}`;
}

public/game/items.js:
// 物品实例与四个容器（xuan/fan/ma 背包 + camp 营地箱）。
// 一件一实例：{uid, itemId, container, uses, obtainedTurn, expiresDay, wet, dirty, ticket}
import { getData, indexById } from './data.js';

const FOOD_IDS = ['meal', 'bread', 'hot_soup'];
export const FOOD_VALUE = { meal: 30, bread: 18, hot_soup: 26 };

// 设计数据之外的两件开局旧设备：不出售、不消耗，只在这里定义。
export const EXTRA_ITEMS = {
  butts: { id: 'butts', name: '捡来的烟头', category: 'tobacco', price: 0, uses: 1, effectText: '翻桶捡的半截烟：精神+2、卫生-3，需要火', shopIds: [] },
  old_camera: { id: 'old_camera', name: '旧相机', category: 'device', price: 0, uses: 1, effectText: '开局带来的旧相机，能拍；耗电量', shopIds: [] },
  old_computer: { id: 'old_computer', name: '旧笔记本', category: 'device', price: 0, uses: 1, effectText: '开局带来的旧电脑，键盘坏了一半', shopIds: [] },
};
export const DURABLE = new Set(['device', 'tool']);

export function itemDef(itemId) {
  if (EXTRA_ITEMS[itemId]) return EXTRA_ITEMS[itemId];
  const items = indexById(getData().items);
  return items[itemId];
}

export function makeItem(state, itemId, container, opts = {}) {
  const def = itemDef(itemId);
  if (!def) throw new Error('未知物品 ' + itemId);
  state.itemSeq = (state.itemSeq || 0) + 1;
  const inst = {
    uid: 'it' + state.itemSeq,
    itemId,
    container,
    uses: def.uses,
    obtainedTurn: state.turn,
    expiresDay: def.shelfLifeDays ? state.day + def.shelfLifeDays : null,
    wet: false,
    dirty: false,
  };
  if (opts.ticket) inst.ticket = opts.ticket;
  state.items.push(inst);
  return inst;
}

export function itemsIn(state, container, itemId = null) {
  return state.items.filter((x) => x.container === container && (!itemId || x.itemId === itemId));
}

export function findItem(state, uid) {
  return state.items.find((x) => x.uid === uid) || null;
}

export function removeItem(state, uid) {
  state.items = state.items.filter((x) => x.uid !== uid);
}

// 角色现在能碰到的容器：自己的包永远可及，营地箱要人在营地。
export function accessibleContainers(state, actorId) {
  const p = state.actors[actorId];
  const out = [actorId];
  if (p.location === 'camp') out.push('camp');
  return out;
}

export function accessibleItems(state, actorId, itemId = null) {
  const cs = accessibleContainers(state, actorId);
  return state.items.filter((x) => cs.includes(x.container) && (!itemId || x.itemId === itemId));
}

export function isFood(itemId) {
  return FOOD_IDS.includes(itemId);
}

export function foodFresh(state, inst) {
  return isFood(inst.itemId) && (inst.expiresDay === null || inst.expiresDay >= state.day);
}

// 有效食物份数：未过期的正餐/面包/热汤。
export function effectiveFood(state) {
  return state.items.filter((x) => foodFresh(state, x)).length;
}

// 消耗一格；用完删除实例。返回是否成功。
export function consumeUse(state, uid, n = 1) {
  const inst = findItem(state, uid);
  if (!inst || inst.uses < n) return false;
  if (DURABLE.has(itemDef(inst.itemId)?.category)) return true;
  inst.uses -= n;
  if (inst.uses <= 0) removeItem(state, uid);
  return true;
}

// 清掉过期食物，返回丢弃份数。
export function discardExpired(state) {
  const before = state.items.length;
  state.items = state.items.filter((x) => !(isFood(x.itemId) && x.expiresDay !== null && x.expiresDay < state.day));
  return before - state.items.length;
}

// 给某人吃一份：自己包优先，再营地箱；先吃快过期的。返回吃到的 itemId 或 null。
export function eatOne(state, actorId) {
  const cands = state.items
    .filter((x) => foodFresh(state, x) && (x.container === actorId || x.container === 'camp'))
    .sort((a, b) => (a.expiresDay ?? 999) - (b.expiresDay ?? 999) || (a.container === actorId ? -1 : 1));
  const inst = cands[0];
  if (!inst) return null;
  removeItem(state, inst.uid);
  return inst.itemId;
}

// 设备只认活人拿得到的：营地箱里的电脑谁都能用（回营取），相机要在包里或营地箱。
export function hasDevice(state, kind) {
  const ids = kind === 'camera' ? ['camera', 'old_camera'] : ['old_computer'];
  return state.items.some((x) => ids.includes(x.itemId) && !x.container.startsWith('relic:'));
}

export function transferItem(state, uid, toContainer) {
  const inst = findItem(state, uid);
  if (!inst) return false;
  inst.container = toContainer;
  return true;
}

// 把一堆实例按 itemId+container 分组给 UI。
export function groupItems(state, container) {
  const map = new Map();
  for (const x of state.items) {
    if (container && x.container !== container) continue;
    const key = x.itemId + '|' + x.container;
    if (!map.has(key)) map.set(key, { itemId: x.itemId, container: x.container, count: 0, uses: 0, uids: [], wet: false, dirty: false, expiresDay: x.expiresDay });
    const g = map.get(key);
    g.count++;
    g.uses += x.uses;
    g.uids.push(x.uid);
    g.wet = g.wet || x.wet;
    g.dirty = g.dirty || x.dirty;
    if (x.expiresDay !== null && (g.expiresDay === null || x.expiresDay < g.expiresDay)) g.expiresDay = x.expiresDay;
  }
  return [...map.values()];
}

