// 路人、熟面孔、履约记录、垃圾桶。路人按（日、街区、时段）确定生成，熟人有记忆。
import { getData } from './data.js';
import { rng, pick, intBetween } from './rng.js';
import { begOutcome, clamp } from './rules.js';
import { makeItem } from './items.js';

export const REGULARS = [
  { id: 'reg_chen', name: '老陈', district: 'station', slots: [0, 1, 2], job: '站口装卸工', tags: ['工友', '直来直去'], gives: 'cash' },
  { id: 'reg_liu', name: '刘姐', district: 'market', slots: [0, 1], job: '早市摊主', tags: ['嘴硬心软', '认人'], gives: 'food' },
  { id: 'reg_zhao', name: '小赵', district: 'cinema', slots: [2, 3], job: '学生', tags: ['爱看涂鸦', '零钱不多'], gives: 'cash' },
  { id: 'reg_wang', name: '王叔', district: 'service', slots: [0, 1, 2, 3], job: '服务站志愿者', tags: ['讲规矩', '记得每个人'], gives: 'tip' },
  { id: 'reg_lu', name: '鲁叔', district: 'recycle', slots: [1, 2], job: '仓库老板', tags: ['要人搬货', '给活不给钱'], gives: 'tip' },
  { id: 'reg_xu', name: '许姐', district: 'cinema', slots: [1, 2], job: '工作间主人', tags: ['看作品说话'], gives: 'tip' },
];

const JOBS = ['外卖骑手', '保洁阿姨', '上班族', '退休大爷', '带孩子的妈妈', '夜班保安', '小店老板', '送货司机', '中学生家长', '游客', '摆摊小贩', '快递员', '面馆伙计', '代驾师傅'];
const MOODS = [
  { key: 'hurried', label: '赶时间' },
  { key: 'good', label: '心情不错' },
  { key: 'annoyed', label: '有点烦' },
  { key: 'idle', label: '闲着' },
  { key: 'offwork', label: '刚下班' },
];

export function regularOf(npcId) {
  return REGULARS.find((r) => r.id === npcId) || null;
}

export function relation(state, npcId) {
  if (!state.relations[npcId]) state.relations[npcId] = { trust: 0, helped: 0, refused: 0, jobs: 0, lastDay: 0 };
  return state.relations[npcId];
}

// 某街区某时段可见的路人（4—6 个），含在场的熟人。
export function passersby(state, district, slot) {
  const key = `npc:${state.day}:${district}:${slot}`;
  const n = intBetween(rng(state.seed, key + ':n'), 4, 6);
  const out = [];
  for (const reg of REGULARS) {
    if (reg.district !== district || !reg.slots.includes(slot)) continue;
    if (rng(state.seed, key + ':' + reg.id) < 0.55) {
      const rel = state.relations[reg.id] || { trust: 0, helped: 0 };
      out.push({ id: reg.id, name: reg.name, job: reg.job, mood: pick(rng(state.seed, key + ':m:' + reg.id), MOODS), regular: true, tags: reg.tags, trust: rel.trust, known: rel.helped > 0 || rel.jobs > 0 });
    }
  }
  for (let i = out.length; i < n; i++) {
    const id = `p:${state.day}:${district}:${slot}:${i}`;
    out.push({ id, name: pick(rng(state.seed, id + ':job'), JOBS), job: '', mood: pick(rng(state.seed, id + ':mood'), MOODS), regular: false, tags: [], trust: 0, known: false });
  }
  for (const npc of out) npc.asked = Boolean(state.daily.begged[npc.id]);
  return out;
}

// 乞讨：最多 3 个目标，每个 npc 全队每天只有一次结果。返回逐人结果。
export function begAt(state, actorId, district, targets, events, style = 'ask') {
  const rules = getData().rules;
  const p = state.actors[actorId];
  // 举纸板：不必开口，被拒不伤精神，但给的少；速写换零钱（凡哥带纸笔）：更少被拒、给得多。
  let perform = false;
  if (style === 'perform' && actorId === 'fan') { const paper = state.items.find((x) => x.itemId === 'paper_set' && x.container === 'fan' && x.uses > 0); if (paper) { paper.uses -= 1; if (paper.uses <= 0) state.items = state.items.filter((x) => x.uid !== paper.uid); perform = true; } }
  const list = passersby(state, district, state.slot);
  const results = [];
  let refusalLoss = 0;
  for (const npcId of targets.slice(0, rules.begging.encountersPerMainAction)) {
    const npc = list.find((x) => x.id === npcId);
    if (!npc || state.daily.begged[npcId]) continue;
    state.daily.begged[npcId] = actorId;
    const r = rng(state.seed, `beg:${state.day}:${npcId}`);
    let shift = 0;
    if (npc.regular) shift += Math.min(10, relation(state, npcId).trust * 3);
    if (perform) shift += 8;
    if (p.hygiene < 20) shift -= 8;
    if (npc.mood.key === 'hurried' && r < 0.12) {
      results.push({ npc, kind: 'refusal', cash: 0, text: `${npc.name}摆摆手：“这会儿赶时间。”` });
      refusalLoss += 1;
      continue;
    }
    let out = begOutcome(r, rules, { refusalShift: Math.max(0, shift) });
    if (shift < 0 && out.kind === 'cash' && rng(state.seed, `begdirty:${state.day}:${npcId}`) < 0.3) out = { kind: 'refusal', cash: 0 };
    // 熟人按自己的路数给：刘姐给饭，王叔/鲁叔/许姐给线索。
    if (npc.regular && out.kind !== 'refusal') {
      const reg = regularOf(npcId);
      if (reg.gives === 'food') out = { kind: 'food', cash: 0 };
      else if (reg.gives === 'tip' && r < 0.6) out = { kind: 'job_tip', cash: 0 };
    }
    if (out.kind === 'refusal') {
      refusalLoss += 1;
      results.push({ npc, kind: 'refusal', cash: 0, text: `${npc.name}摇了摇头。` });
      continue;
    }
    if (out.kind === 'cash') {
      let cash = out.cash;
      if (style === 'sign') cash = Math.max(1, cash - 1);
      if (perform) cash += 4;
      state.cash += cash;
      state.ledger.income += cash;
      results.push({ npc, kind: 'cash', cash, text: `${npc.name}${perform ? '看了画像，' : ''}给了${cash}块零钱。` });
    } else if (out.kind === 'food') {
      makeItem(state, 'meal', actorId);
      results.push({ npc, kind: 'food', cash: 0, text: `${npc.name}把一份没动过的饭递了过来。` });
    } else if (out.kind === 'job_tip') {
      state.pendingJobTips.push({ district, day: state.day, from: npc.name, npcId });
      results.push({ npc, kind: 'job_tip', cash: 0, text: `${npc.name}说下一时段那边缺人手，让你们去问问。` });
    }
    if (npc.regular) {
      const rel = relation(state, npcId);
      rel.helped += 1;
      rel.trust = clamp(rel.trust + 1, 0, 5);
      rel.lastDay = state.day;
    }
  }
  // 普通拒绝每日每人精神损失上限 2。
  const already = state.daily.refusalLoss[actorId] || 0;
  const loss = style === 'sign' ? 0 : Math.min(refusalLoss, Math.max(0, rules.begging.dailyRefusalMindLossCap - already));
  state.daily.refusalLoss[actorId] = already + loss;
  if (loss > 0) p.mind = clamp(p.mind - loss);
  const cash = results.reduce((a, x) => a + x.cash, 0);
  events.push(`${state.names[actorId]}在${districtName(district)}${style === 'sign' ? '举着纸板' : perform ? '画速写换零钱' : '开口求助'}${results.length}次：${results.map((x) => x.text).join('') || '没有人可以问。'}${loss ? `（被拒精神-${loss}）` : ''}`);
  return { results, cash };
}

export function districtName(id) {
  return getData().districts.find((d) => d.id === id)?.name || id;
}

// 每日一次的短聊：少量恢复，不给钱。
export function chatWith(state, actorId, npcId) {
  const p = state.actors[actorId];
  if (p.life !== 'active') return { error: '现在不能聊天' };
  if (state.daily.chatted[actorId]) return { error: '今天已经聊过一次了，再聊不加精神' };
  state.daily.chatted[actorId] = npcId;
  p.mind = clamp(p.mind + 2);
  if (regularOf(npcId)) relation(state, npcId).lastDay = state.day;
  return { ok: true };
}

// 垃圾桶：每街区两只，每日各一次；结果可预见范围，不掷病骰（不洁食物在吃下时记暴露）。
const BINS = { market: ['市场口垃圾桶', '早餐摊后巷桶'], station: ['站口垃圾桶', '西侧空地桶'], recycle: ['回收巷大桶', '零件堆边桶'] };

export function binsAvailable(state, district) {
  return (BINS[district] || []).map((name, i) => ({ id: `${district}:${i}`, name, used: Boolean(state.daily.bins[`${district}:${i}`]) }));
}

export function digBins(state, actorId, district, events) {
  const avail = binsAvailable(state, district).filter((b) => !b.used);
  const found = [];
  for (const bin of avail.slice(0, 2)) {
    state.daily.bins[bin.id] = actorId;
    const r = rng(state.seed, `bin:${state.day}:${bin.id}`);
    if (r < 0.28) { const it = makeItem(state, 'bread', actorId); it.dirty = true; found.push('一包没开封但来路不明的面包'); }
    else if (r < 0.46) { const n = intBetween(rng(state.seed, `binb:${state.day}:${bin.id}`), 2, 5); state.bottles = (state.bottles || 0) + n; found.push(n + '个瓶罐'); }
    else if (r < 0.58) { makeItem(state, 'butts', actorId); found.push('几个还能抽的烟头'); }
    else if (r < 0.7) { state.cloth += 1; found.push('几块能用的布料'); }
    else if (r < 0.8) { state.parts += 1; found.push('一块电子零件'); }
    else if (r < 0.86) { const c = intBetween(rng(state.seed, `binc:${state.day}:${bin.id}`), 1, 4); state.cash += c; state.ledger.income += c; found.push(c + '块零钱'); }
    else if (r < 0.92) { state.wood += 1; found.push('一块木板'); }
    else if (r < 0.95) { const it = makeItem(state, 'soap', actorId); it.uses = 1; found.push('一小块用剩的肥皂'); }
    else found.push('什么也没有');
  }
  events.push(`${state.names[actorId]}翻了${avail.length ? districtName(district) + '的' + avail.length + '只垃圾桶：' + found.join('、') : '空桶：今天这里已经翻过了'}。`);
  return found;
}

// 捡瓶罐：沿街走一圈，3—8 个；同街区当天第二次递减。
export function collectBottles(state, actorId, district, events) {
  const key = `bottles:${state.day}:${district}`;
  const times = state.daily[key] || 0;
  state.daily[key] = times + 1;
  let n = intBetween(rng(state.seed, key + ':' + times), 3, 8);
  n = Math.max(1, n - times * 2);
  state.bottles = (state.bottles || 0) + n;
  events.push(`${state.names[actorId]}在${districtName(district)}捡了${n}个瓶罐（共${state.bottles}）。`);
  return n;
}

public/game/rng.js:
// 可复现随机：同一 seed 与 key 永远得到同一个数，存档刷新不换结果。
// 彩票在购买时用 ticketId 作 key 锁定，刮开只是演出。

export function rng(seed, key) {
  let h = (seed ^ 2166136261) >>> 0;
  const s = String(key);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  h ^= h >>> 16;
  h = Math.imul(h, 0x7feb352d);
  h ^= h >>> 15;
  h = Math.imul(h, 0x846ca68b);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

// 按整数权重抽下标；weights 之和不要求是 100。
export function weightedIndex(r, weights) {
  const total = weights.reduce((a, b) => a + b, 0);
  let x = r * total;
  for (let i = 0; i < weights.length; i++) {
    x -= weights[i];
    if (x < 0) return i;
  }
  return weights.length - 1;
}

export function pick(r, list) {
  if (!list.length) return undefined;
  return list[Math.min(list.length - 1, Math.floor(r * list.length))];
}

export function intBetween(r, lo, hi) {
  return lo + Math.floor(r * (hi - lo + 1));
}

public/game/rules.js:
// 无状态纯规则：只吃数字，不碰 state。数值出处见策划 01 的章节号与 03 JSON 的 rules。
// 全部是虚构游戏参数，不模拟现实医疗、赔率或剂量。

export const clamp = (v, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, v));

// 07 愿望：单条愿望本回合的精神损失。60-84 扣 1，85-100 扣 2。
export function wishMindLoss(intensity, rules) {
  const d = rules.desire;
  if (intensity >= d.highThreshold) return d.highMindLoss;
  if (intensity >= d.midThreshold) return d.midMindLoss;
  return 0;
}

// 07 多条愿望叠加封顶（默认每人每回合 3）。
export function wishPressure(intensities, rules) {
  const cap = rules.desire.mindLossCapPerActorPerTurn;
  const sum = intensities.reduce((a, x) => a + wishMindLoss(x, rules), 0);
  return Math.min(cap, sum);
}

// 07 强度分段的人物反应，UI 直接用。
export function wishStage(intensity) {
  if (intensity >= 85) return { key: 'obsessed', label: '反复纠结', hint: '执念，每回合精神-2' };
  if (intensity >= 60) return { key: 'nagging', label: '一直惦记', hint: '情绪受影响，每回合精神-1' };
  if (intensity >= 45) return { key: 'asked', label: '明确提出', hint: '已直接开口，给安排空间' };
  if (intensity >= 25) return { key: 'hinting', label: '暗示', hint: '多看两眼、转移话题' };
  return { key: 'idle', label: '只是念头', hint: '' };
}

// 08 精神危机链：一个行动回合更新一次，夜间不重复调用。
// state: {mind, zeroTurns, crisis, health}；pressure 为本回合愿望压力（已封顶），recovery 为本回合恢复量。
export function mindStep(state, pressure, recovery = 0, rules) {
  const mc = rules.mentalCrisis;
  const cap = rules.desire.mindLossCapPerActorPerTurn;
  let mind = clamp(state.mind + recovery - Math.min(cap, Math.max(0, pressure)));
  let zeroTurns = state.zeroTurns;
  let crisis = state.crisis;
  if (mind >= mc.recoveryMindThreshold) {
    zeroTurns = 0;
    crisis = false;
  } else if (mind === mc.triggerMind) {
    zeroTurns += 1;
    if (zeroTurns >= mc.consecutiveTurns) crisis = true;
  } else if (!crisis) {
    zeroTurns = 0;
  }
  const damage = crisis ? (mind === 0 ? mc.zeroMindHealthDamage : mc.lowMindHealthDamage) : 0;
  return { mind, zeroTurns, crisis, health: clamp(state.health - damage), damage };
}

// 09 每日一次暴露检定的概率。
export function hygieneRisk(hygiene, flags = {}, rules) {
  const h = rules.hygiene;
  let extra = 0;
  for (const [floor, add] of h.hygieneRiskBuckets) {
    if (hygiene >= floor) { extra = add; break; }
  }
  let p = h.baseRisk + extra;
  if (flags.dirtyFood) p += h.dirtyFoodExtra;
  if (flags.openWound) p += h.uncoveredWoundExtra;
  if (flags.care) p -= h.careReduction;
  return Math.min(h.riskCap, Math.max(0, Math.round(p * 1000) / 1000));
}

// 10 病情分段：返回每回合健康消耗与标签。
export function diseaseStage(severity, rules) {
  if (severity <= 0) return { stage: 0, label: '已缓解', damage: 0 };
  for (const [lo, hi, dmg] of rules.disease.healthDamageStages) {
    if (severity >= lo && severity <= hi) {
      const label = lo >= 85 ? '危重' : lo >= 60 ? '重度' : lo >= 30 ? '中度' : '轻度';
      return { stage: lo >= 85 ? 3 : lo >= 60 ? 2 : lo >= 30 ? 1 : 0, label, damage: dmg };
    }
  }
  return { stage: 0, label: '轻度', damage: 0 };
}

// 10 一个行动回合的病情推进。flags: dirty（卫生<25 或脏污工作）、matchingCare、rest、safeSleep（仅夜间轻症）。
export function diseaseStep(severity, health, flags = {}, rules) {
  if (severity <= 0) return { severity: 0, health, damage: 0 };
  const d = rules.disease;
  let growth = d.untreatedGrowthPerTurn;
  if (flags.dirty) growth += d.badHygieneExtra;
  if (flags.matchingCare) growth -= d.matchingCareReduction;
  if (flags.rest) growth -= d.restReduction;
  if (flags.safeSleep && severity < 30) growth -= d.safeSleepMildSeverityReduction;
  const next = clamp(severity + growth);
  const stage = diseaseStage(next, rules);
  return { severity: next, health: clamp(health - stage.damage), damage: stage.damage };
}

// 10.3 护理生效的四个条件缺一不可：有用品、计划匹配、真的安排了护理、同一容器可及。
export function canApplyCare({ hasSupply, matchedPlan, committedCare, sameContainerAccess }) {
  return Boolean(hasSupply && matchedPlan && committedCare && sameContainerAccess);
}

// 15 濒死：T 回合末健康 0，普通到 T+1 末，马哥首次到 T+2 末（整局一次）。
export function makeDowned(actorId, turn, gritUsed, rules) {
  const r = rules.rescue;
  const extra = actorId === rules.join.actorId && !gritUsed;
  return {
    deadline: turn + (extra ? r.maFirstFollowingTurns : r.standardFollowingTurns),
    gritUsed: gritUsed || extra,
    extra,
  };
}

// 15 期限判定：先救援后判死。
export function resolveDeadline(life, deadline, turn, rescued) {
  if (life !== 'downed') return life;
  if (rescued) return 'active';
  return turn >= deadline ? 'dead' : 'downed';
}

// 04 彩票：购买时按购票人牌彩运锁定返还（含本金）。
export function ticketOutcome(actorId, r, rules) {
  const g = rules.gambling;
  const weights = actorId === 'ma' ? g.ticketWeights.ma : g.ticketWeights.others;
  const total = weights.reduce((a, b) => a + b, 0);
  let x = r * total;
  for (let i = 0; i < weights.length; i++) {
    x -= weights[i];
    if (x < 0) return g.ticketGrossPayouts[i];
  }
  return g.ticketGrossPayouts[g.ticketGrossPayouts.length - 1];
}

// 06 抽象牌局：入场 10，返还 20/10/0 含本金。
export function cardOutcome(actorId, r, rules) {
  const g = rules.gambling;
  const weights = actorId === 'ma' ? g.cardWeights.ma : g.cardWeights.others;
  const total = weights.reduce((a, b) => a + b, 0);
  let x = r * total;
  for (let i = 0; i < weights.length; i++) {
    x -= weights[i];
    if (x < 0) return g.cardGrossPayouts[i];
  }
  return 0;
}

// 05 一次乞讨接触。modifiers.refusalShift 把拒绝权重挪给小额零钱（声望/技能用），不改总和。
export function begOutcome(r, rules, modifiers = {}) {
  const b = rules.begging;
  const weights = b.weights.slice();
  const shift = Math.max(0, Math.min(weights[0], modifiers.refusalShift || 0));
  weights[0] -= shift;
  weights[1] += shift;
  const total = weights.reduce((a, x) => a + x, 0);
  let x = r * total;
  for (let i = 0; i < weights.length; i++) {
    x -= weights[i];
    if (x < 0) return { kind: b.outcomeKinds[i], cash: b.currencyOutcomes[i] };
  }
  return { kind: 'refusal', cash: 0 };
}

// 04 饭钱保护：max(0, 存活入队人数×2 − 有效食物份数)×8，另加已确认护理费。
export function foodReserve(aliveCount, effectiveFood, rules, careCommitted = 0) {
  return Math.max(0, aliveCount * rules.foodPerLivingActorPerDay - effectiveFood) * rules.foodPrice + careCommitted;
}

// 04 §06 对话输出契约校验。返回 {ok, reason}。
const DIALOGUE_KEYS = ['requestId', 'sceneId', 'stateRevision', 'lines', 'choiceLabels', 'desireCueRefs'];

export function validateDialogue(payload, context) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return bad('不是对象');
  const keys = Object.keys(payload).sort();
  if (keys.join(',') !== DIALOGUE_KEYS.slice().sort().join(',')) return bad('字段集合不符');
  for (const k of ['requestId', 'sceneId', 'stateRevision']) {
    if (payload[k] !== context[k]) return bad(k + ' 不匹配');
  }
  const lines = payload.lines;
  if (!Array.isArray(lines) || lines.length < 1 || lines.length > 6) return bad('lines 数量越界');
  for (const line of lines) {
    if (!line || typeof line !== 'object' || Object.keys(line).sort().join(',') !== 'speakerId,text') return bad('line 结构错误');
    if (!context.allowedCast.includes(line.speakerId)) return bad('说话人不在场或已死亡');
    if (typeof line.text !== 'string' || line.text.length < 1 || line.text.length > 160) return bad('台词长度越界');
    if (/[<>]/.test(line.text)) return bad('台词含标签字符');
  }
  const labels = payload.choiceLabels;
  if (!Array.isArray(labels)) return bad('choiceLabels 不是数组');
  const ids = [];
  for (const l of labels) {
    if (!l || typeof l !== 'object' || Object.keys(l).sort().join(',') !== 'choiceId,label') return bad('choiceLabel 结构错误');
    if (typeof l.label !== 'string' || l.label.length < 1 || l.label.length > 80) return bad('选项标签长度越界');
    ids.push(l.choiceId);
  }
  if (new Set(ids).size !== ids.length || ids.length !== context.requiredChoiceIds.length ||
      ids.some((id) => !context.requiredChoiceIds.includes(id))) return bad('选项集合与要求不符');
  const refs = payload.desireCueRefs;
  if (!Array.isArray(refs) || refs.some((x) => !context.allowedWishIds.includes(x))) return bad('引用了不允许的愿望');
  return { ok: true };
}

// 04 §08 事件提案校验。
export function validateEventProposal(payload, context) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return bad('不是对象');
  if (payload.requestId !== context.requestId) return bad('requestId 不匹配');
  if (payload.status === 'no_event') {
    if (Object.keys(payload).sort().join(',') !== 'requestId,status') return bad('无事件字段集合不符');
    return { ok: true, empty: true };
  }
  if (payload.status !== 'proposal') return bad('status 非法');
  if (!context.templateIds.includes(payload.templateId)) return bad('模板不在白名单');
  if (!context.themeIds.includes(payload.themeId)) return bad('主题不在白名单');
  if (!context.choiceBundleIds.includes(payload.choiceBundleId)) return bad('选项包不在白名单');
  if (!Array.isArray(payload.castIds) || payload.castIds.some((x) => !context.castIds.includes(x))) return bad('参与者不合法');
  if (typeof payload.title !== 'string' || payload.title.length < 1 || payload.title.length > 40) return bad('标题长度越界');
  if (typeof payload.setup !== 'string' || payload.setup.length < 1 || payload.setup.length > 200) return bad('情境长度越界');
  if (!Array.isArray(payload.choices) || payload.choices.length < 2 || payload.choices.length > 3) return bad('选项数量越界');
  const ids = new Set();
  for (const c of payload.choices) {
    if (!c || typeof c !== 'object' || Array.isArray(c) || Object.keys(c).sort().join(',') !== 'choiceId,label') return bad('选项结构错误');
    if (!context.choiceIds.includes(c.choiceId)) return bad('choiceId 不在白名单');
    if (ids.has(c.choiceId)) return bad('选项重复');
    ids.add(c.choiceId);
    if (typeof c.label !== 'string' || c.label.length < 1 || c.label.length > 40) return bad('选项文字长度越界');
  }
  for (const k of Object.keys(payload)) {
    if (!['requestId', 'status', 'templateId', 'themeId', 'choiceBundleId', 'castIds', 'title', 'setup', 'choices'].includes(k)) return bad('越权字段 ' + k);
  }
  return { ok: true };
}

function bad(reason) {
  return { ok: false, reason };
}

public/game/save.js:
// 存档校验：只接受 v3 结构；旧 v2（28 日）存档给出明确的不兼容说明，不偷偷迁移。
import { IDS } from './engine.js';

export const SAVE_KEY = 'jinwan-shui-naer-v3';

export function validateSave(s) {
  try {
    if (!s || typeof s !== 'object') return { ok: false, reason: '不是存档对象' };
    if (s.version === 2) return { ok: false, reason: '这是旧版 28 日原型存档，100 日版不自动迁移；请新开局' };
    if (s.version !== 3) return { ok: false, reason: '存档版本不识别' };
    if (!Number.isInteger(s.seed) || !Number.isInteger(s.day) || s.day < 1 || s.day > 100) return { ok: false, reason: '日期或种子无效' };
    if (![0, 1, 2, 3].includes(s.slot) || !Number.isInteger(s.turn) || s.turn < 0 || s.turn > 402) return { ok: false, reason: '回合无效' };
    if (!['planning', 'meeting', 'tail', 'ending', 'gameover'].includes(s.phase)) return { ok: false, reason: '阶段无效' };
    if (!Number.isInteger(s.cash) || s.cash < 0 || s.cash > 10000000) return { ok: false, reason: '现金无效' };
    for (const id of IDS) {
      const p = s.actors?.[id];
      if (!p || !['unrecruited', 'active', 'downed', 'dead'].includes(p.life)) return { ok: false, reason: '角色状态无效' };
      for (const k of ['health', 'food', 'energy', 'warmth', 'mind', 'hygiene']) if (!Number.isInteger(p[k]) || p[k] < 0 || p[k] > 100) return { ok: false, reason: '角色数值越界' };
      if (!Array.isArray(s.plan?.[id]) || s.plan[id].length !== 4) return { ok: false, reason: '排程结构无效' };
    }
    if (!Array.isArray(s.items) || !Array.isArray(s.wishes) || !Array.isArray(s.events) || !s.shops || !s.daily) return { ok: false, reason: '缺少子系统数据' };
    if (s.items.length > 2000 || s.wishes.length > 500 || s.events.length > 500) return { ok: false, reason: '存档异常膨胀' };
    for (const it of s.items) if (typeof it.uid !== 'string' || typeof it.itemId !== 'string' || typeof it.container !== 'string') return { ok: false, reason: '物品实例无效' };
    if (s.ledger.start + s.ledger.income - s.ledger.expense !== s.cash) return { ok: false, reason: '账本与现金对不上' };
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: '存档损坏：' + e.message };
  }
}

public/game/settle.js:
// 回合结算：预检（整格失败不扣费）→ 执行 → 吃饭与环境 → 愿望/精神/疾病 → 濒死与死亡 → 夜间 → 新一日。
import { getData, indexById } from './data.js';
import { rng } from './rng.js';
import { clamp, makeDowned, cardOutcome } from './rules.js';
import { ACTIONS } from './actions.js';
import { IDS, NAMES, SLOTS, copy, alive, active, reserve, energyCost, foodEquivalent, task, cancelAt, freshDaily } from './engine.js';
import { makeItem, itemsIn, consumeUse, eatOne, discardExpired, hasDevice, FOOD_VALUE, findItem } from './items.js';
import { restockMorning, validateCart, executeCart, shopClosedReason, shopDef } from './shop.js';
import { generateMorningWishes, tickWishes, fulfillWish } from './wishes.js';
import { addDisease, progressDiseases, mentalTick, nightExposure } from './health.js';
import { begAt, digBins, collectBottles, passersby, relation } from './npcs.js';
import { directorTick, settleReserved, misfortuneLine } from './events.js';
import { weatherOf, morningNode, nightScripted, computeEnding } from './story.js';
import { generateFace } from './tickets.js';

const R = () => getData().rules;

export function units(s) {
  const result = [], seen = new Set();
  for (const id of alive(s)) {
    const t = s.plan[id][s.slot];
    if (!t) { result.push({ actor: id, task: null }); continue; }
    const key = t.group || id;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push({ actor: id, task: t, action: ACTIONS[t.id] });
  }
  return result;
}

function needsItem(s, actorId, itemId, zone) {
  return s.items.some((x) => x.itemId === itemId && x.uses > 0 && !x.wet && (x.container === actorId || (zone === 'camp' && x.container === 'camp')));
}

export function preflight(s) {
  if (s.phase === 'tail') return preflightTail(s);
  if (s.phase !== 'planning') return { error: '请先处理当前剧情或结算画面。' };
  if (s.pendingMorning) return { error: '先处理今天的晨间节点。' };
  const jobs = units(s), costs = {}, equip = new Set(), counts = { ...s.daily.orders };
  let bets = s.daily.bets, vouchers = s.vouchers, bedAdds = 0, campAdds = 0;
  const funding = [];
  for (const j of jobs) {
    const { actor: id, task: t, action: a } = j;
    const where = { actorId: id, slot: s.slot };
    if (!t || !a) return { error: '请为' + NAMES[id] + '安排' + SLOTS[s.slot] + '。', ...where };
    if (a.allowed && !a.allowed.includes(s.slot)) return { error: a.name + '不在当前时段开放。', ...where };
    if (a.risky && s.turn < 3) return { error: '教学阶段不开放危险作业。', ...where };
    if (a.fixed && a.fixed.slice().sort().join() !== t.participants.slice().sort().join()) return { error: '职业合作参与者不正确。', ...where };
    if (a.min && t.participants.length !== a.min) return { error: a.name + '需要' + a.min + '人。', ...where };
    if (!a.min && !a.fixed && (t.participants.length !== 1 || t.participants[0] !== id)) return { error: '单人行动的参与者错误。', ...where };
    if (a.rescue && (!t.target || !t.participants.includes(t.target) || s.actors[t.target].life !== 'downed')) return { error: '救援目标已变化，请重排。', ...where };
    if (a.eventOnly) { const ev = s.events.find((e) => e.uid === t.eventUid); if (!ev || ev.status !== 'reserved' || s.turn >= ev.expiresTurn) return { error: '「' + a.name + '」对应的机会已经过期，请重排这一格。', ...where }; }
    if (a.shop) { const closed = shopClosedReason(s, a.shop, s.slot); if (closed) return { error: shopDef(a.shop).name + '：' + closed, ...where }; }
    if (a.shopping && t.cart && t.cart.length) { const v = validateCart(s, id, t.zone, s.slot, t.cart); if (v.error) return { error: v.error, ...where }; }
    if (a.needs && !needsItem(s, id, a.needs, t.zone)) return { error: NAMES[id] + '手边没有可用的' + indexById(getData().items)[a.needs].name + '（要在自己包里，或人在营地时在营地箱）。', ...where };
    for (const m of t.participants) {
      const p = s.actors[m], mt = s.plan[m][s.slot];
      if (!mt || JSON.stringify(mt) !== JSON.stringify(t)) return { error: '合作绑定不完整，请重新选择参与者。', actorId: m, slot: s.slot };
      if (a.rescue && m === t.target) continue;
      if (p.life !== (a.downedOnly ? 'downed' : 'active')) return { error: NAMES[m] + '的生命状态不允许当前行动。', actorId: m, slot: s.slot };
      if (a.who !== 'any' && a.who !== m) return { error: '角色不能做这项专属工作。', actorId: m, slot: s.slot };
      if (p.life === 'active') {
        if (a.complex && p.mind < 20) return { error: NAMES[m] + '精神不足20，请改基础工作、免费爱好或休整。', actorId: m, slot: s.slot };
        if ((a.risky || a.complex) && p.intox >= 2) return { error: NAMES[m] + '醉意较高，不能危险作业或复杂专注工作。', actorId: m, slot: s.slot };
        if (a.gamble && p.intox > 0) return { error: NAMES[m] + '有醉意，本回合不能付费博彩。', actorId: m, slot: s.slot };
        if (p.energy < energyCost(s, m, a)) return { error: NAMES[m] + '体力不足（需' + energyCost(s, m, a) + '），请休整或选择轻活。', actorId: m, slot: s.slot };
        if (p.diseases.some((d) => d.severity >= 85) && (a.work || a.risky)) return { error: NAMES[m] + '病情危重，不能照常干活。', actorId: m, slot: s.slot };
      }
    }
    for (const e of a.equip || []) {
      if (equip.has(e)) return { error: '唯一' + (e === 'computer' ? '电脑' : '相机') + '同槽被重复占用，请调整时段。', ...where };
      if (!hasDevice(s, e)) return { error: '没有可用的' + (e === 'computer' ? '电脑' : '相机') + '。', ...where };
      equip.add(e);
    }
    counts[t.id] = (counts[t.id] || 0) + 1;
    if (a.limit && counts[t.id] > a.limit) return { error: a.name + '的本日岗位/次数已用完。', ...where };
    if (a.gamble && ++bets > R().gambling.paidActionsTeamDailyCap) return { error: '全队今日付费博彩已达2次（购票与牌局共用），可选无赌注纸牌。', ...where };
    bedAdds += a.beds || 0; campAdds += a.camp || 0;
    let cost = { ...(a.cost || {}) };
    if (t.costOverride !== null && t.costOverride !== undefined) cost.cash = t.costOverride;
    for (const [k, v] of Object.entries(t.extraCost || {})) cost[k] = (cost[k] || 0) + v;
    if (t.cart && t.cart.length) { const v = validateCart(s, id, t.zone, s.slot, t.cart); cost.cash = (cost.cash || 0) + v.total; }
    let useVoucher = false;
    if (a.aid) { if (vouchers > 0) { vouchers--; useVoucher = true; } else cost.cash = R().rescue.serviceCost; }
    for (const [k, v] of Object.entries(cost)) costs[k] = (costs[k] || 0) + v;
    funding.push({ ...j, cost, useVoucher });
  }
  if (s.camp.beds + bedAdds > 3) return { error: '床位上限3。' };
  if (s.camp.rain + campAdds > 3) return { error: '防雨等级上限3。' };
  const labels = { cash: '现金', parts: '零件', battery: '电量', wood: '木料', cloth: '布料' };
  for (const [k, v] of Object.entries(costs)) if (s[k] < v) return { error: labels[k] + '不足：本回合需' + v + '，现有' + s[k] + '。整回合未执行、未扣费。' };
  const leisureCash = funding.filter((j) => j.action.leisure || j.action.gamble || (j.task.cart && j.task.cart.some((l) => l.itemId === 'ticket'))).reduce((a, j) => a + (j.cost.cash || 0), 0);
  if (leisureCash > 0 && s.cash - (costs.cash || 0) < reserve(s)) return { error: '这会动用预留的饭钱' + reserve(s) + '。先补食物或安排劳动。' };
  return { jobs: funding, costs, counts, bets };
}

function preflightTail(s) {
  const jobs = units(s);
  for (const j of jobs) {
    if (!j.task) continue;
    if (!['aid', 'rescue', 'wait', 'rest'].includes(j.task.id)) return { error: '尾声回合只处理救援：' + NAMES[j.actor] + '请改为救援、联系救助或休息。' };
  }
  return { jobs: jobs.filter((j) => j.task).map((j) => ({ ...j, cost: j.action.aid ? (s.vouchers > 0 ? {} : { cash: R().rescue.serviceCost }) : j.action.cost || {}, useVoucher: j.action.aid && s.vouchers > 0 })), costs: {}, counts: {}, bets: 0 };
}

function setDowned(s, id, turn, cause, events) {
  const p = s.actors[id];
  if (p.life !== 'active' || p.health > 0) return;
  if (turn <= 3) { p.health = 1; events.push(NAMES[id] + '受到前三回合教学保护。'); return; }
  const r = makeDowned(id, turn, p.gritUsed, R());
  p.life = 'downed'; p.downedAt = turn; p.deadline = r.deadline; p.deathCause = cause; p.gritUsed = r.gritUsed;
  events.push(NAMES[id] + '濒死：' + cause + '。须在回合' + p.deadline + '结束前获救。' + (r.extra ? '命硬：整局唯一的额外1回合已启用。' : ''));
}

function kill(s, id, turn, events) {
  const p = s.actors[id];
  if (p.life === 'dead') return;
  p.life = 'dead'; p.health = 0; p.deathTurn = turn; p.deadline = null;
  s.deaths.push({ id, day: s.day, turn, cause: p.deathCause || '救援未及时完成' });
  for (const it of s.items) if (it.container === id) it.container = 'relic:' + id;
  for (const w of s.wishes) if (w.actor === id && w.status === 'active') { w.status = 'closed'; w.closedDay = s.day; }
  events.push(NAMES[id] + '死亡。已取消其后续劳动和合作；幸存者继续。');
  for (const m of alive(s)) { s.actors[m].mind = clamp(s.actors[m].mind - 18); s.actors[m].grief = 3; }
}

function recover(s, id, events) {
  const p = s.actors[id];
  p.life = 'active'; p.health = R().rescue.restoredHealth; p.energy = Math.max(p.energy, 20); p.warmth = Math.max(35, p.warmth);
  p.mind = Math.max(p.mind, R().rescue.restoredMindMinimum); p.downedAt = null; p.deadline = null; p.deathCause = null; p.careProtect = true; p.crisis = false; p.zeroTurns = 0; p.location = 'service';
  events.push(NAMES[id] + '已获救：健康25、精神至少20。本格受安全照护保护，请继续安排休整。');
}

function cleanupFuture(s, start) {
  for (const id of IDS) {
    if (!['downed', 'dead'].includes(s.actors[id].life)) continue;
    for (let k = start; k < 4; k++) { cancelAt(s, id, k); if (s.actors[id].life === 'downed') s.plan[id][k] = task('wait', [id]); }
  }
}

const NON_REPEAT = new Set(['shop', 'beg', 'bins', 'cards', 'observe', 'oddjob', 'rescue', 'aid', 'wait', 'clinic', 'bath', 'graffiti', 'laundry', 'campclean', 'roof', 'bed', 'helper', 'trio', 'coop', 'danger', 'talk']);
export function nextPlan(s) {
  const fallback = { xuan: ['scavenge', 'repair', 'joke', 'rest'], fan: ['kitchen', 'sketch', 'sketch', 'rest'], ma: ['run', 'run', 'rest', 'freecards'] };
  const result = {};
  for (const id of IDS) {
    const p = s.actors[id];
    result[id] = [0, 1, 2, 3].map((k) => {
      if (p.life === 'downed') return task('wait', [id]);
      if (p.life !== 'active') return null;
      const prev = s.plan[id][k];
      if (prev && !prev.group && !NON_REPEAT.has(prev.id) && ACTIONS[prev.id].zone !== 'pick') return task(prev.id, [id]);
      return task(fallback[id][k], [id]);
    });
  }
  return result;
}

function chargeCosts(s, costs) {
  let expense = 0;
  for (const [k, v] of Object.entries(costs)) { s[k] -= v; if (k === 'cash') expense += v; }
  return expense;
}

export function settle(input) {
  if (input.phase === 'tail') return settleTail(input);
  const check = preflight(input);
  if (check.error) return { state: input, error: check.error, at: check.actorId ? { actorId: check.actorId, slot: check.slot } : null };
  const s = copy(input), events = [], T = s.turn + 1, slot = s.slot, day = s.day, startAlive = alive(input);
  const wx = weatherOf(s.seed, day);
  const damage = {}, zones = {}, cared = {}, rested = {}, indoor = {}, mindGain = {}, dirtyWork = {};
  const moves = [], arrivals = [];
  let income = 0, expense = chargeCosts(s, check.costs);
  for (const { actor: id, task: t, action: a, useVoucher } of check.jobs) {
    if (useVoucher) s.vouchers--;
    for (const m of t.participants) { zones[m] = t.zone; rested[m] = Boolean(a.rest); indoor[m] = Boolean(a.indoor); mindGain[m] = (mindGain[m] || 0) + (a.mind || 0); dirtyWork[m] = Boolean(a.dirty); }
    if (a.aid) { recover(s, id, events); continue; }
    if (a.rescue) recover(s, t.target, events);
    let pay = t.pay ?? a.cash ?? 0;
    if (pay) { s.cash += pay; income += pay; }
    for (const [k, v] of Object.entries(a.gain || {})) s[k] += v;
    if (a.foodGain) { for (let i = 0; i < a.foodGain; i++) makeItem(s, 'meal', 'camp'); }
    s.camp.rain += a.camp || 0; s.camp.beds += a.beds || 0; s.footage += a.footage || 0; s.art += a.art || 0;
    if (a.battery) s.battery = Math.min(5, s.battery + a.battery);
    if (a.begging) { const r = begAt(s, id, t.zone, t.targets || passersby(s, t.zone, slot).filter((n) => !n.asked).map((n) => n.id), events, t.style || 'ask'); income += r.cash; }
    if (a.bins) digBins(s, id, t.zone, events);
    if (a.bottles) collectBottles(s, id, t.zone, events);
    if (a.freeMeal) { makeItem(s, 'meal', id); events.push(`${NAMES[id]}在服务站领到一份免费餐。`); }
    if (a.shopping) {
      if (t.cart && t.cart.length) {
        const v = validateCart(s, id, t.zone, slot, t.cart);
        const made = executeCart(s, id, t.cart, t.destination);
        const tickets = made.filter((x) => x.ticket);
        if (tickets.length) { s.daily.bets -= tickets.length - 1; for (const it of tickets) { it.ticket.face = generateFace(s.seed, it.ticket); it.ticket.revealed = []; } fulfillWish(s, id, 'ma_lottery', 'exact', events); s.flags.gambles = (s.flags.gambles || 0) + 1; }
        for (const it of made) { if (['keyboard', 'headphones'].includes(it.itemId) && id === 'xuan') fulfillWish(s, 'xuan', it.itemId === 'keyboard' ? 'xuan_keyboard' : 'xuan_headphones', 'exact', events); if (it.itemId === 'shoes' && id === 'ma') fulfillWish(s, 'ma', 'ma_shoes', 'exact', events); }
        events.push(`${NAMES[id]}到店买了${t.cart.map((l) => indexById(getData().items)[l.itemId].name + '×' + l.qty).join('、')}，花${v.total}。`);
      } else arrivals.push({ actorId: id, zone: t.zone, slot });
    }
    if (a.wash) { const p = s.actors[id]; let gain = a.hygiene; const soap = itemsIn(s, id, 'soap')[0]; if (soap) { consumeUse(s, soap.uid); gain = 25; } if (itemsIn(s, id, 'towel')[0]) gain += 5; p.hygiene = clamp(p.hygiene + gain); events.push(`${NAMES[id]}在水点洗漱，卫生+${gain}${soap ? '（用了肥皂）' : ''}。`); }
    if (a.laundry) { const p = s.actors[id]; if (a.needs) { const det = s.items.find((x) => x.itemId === 'detergent' && (x.container === id || x.container === 'camp')); if (det) consumeUse(s, det.uid); } p.clothes = { dirty: false, wet: true, dirtyDays: 0 }; fulfillWish(s, id, 'clean_clothes_wish', 'partial', events); if (a.hygiene >= 55) { p.hygiene = clamp(p.hygiene + a.hygiene); events.push(`${NAMES[id]}洗了澡也洗了衣服：卫生+${a.hygiene}，衣服今晚是湿的。`); } else events.push(`${NAMES[id]}洗了衣服，晾着，今晚是湿的。`); }
    if (a.campClean) { let n = a.campClean; const bag = s.items.find((x) => x.itemId === 'trash_bag' && x.container === 'camp'); if (bag) { consumeUse(s, bag.uid); n += 20; } s.camp.dirt = clamp(s.camp.dirt - n); events.push(`营地整理：脏污-${n}，现在${s.camp.dirt}。`); }
    if (a.clinic) { const p = s.actors[id]; const d = p.diseases.find((x) => !x.known) || p.diseases.find((x) => !x.plan); if (d) { d.known = true; d.plan = true; events.push(`诊所评估：${NAMES[id]}确诊${d.kind === 'gut' ? '肠胃不适' : d.kind === 'skin' ? '皮肤感染' : d.kind === 'wound' ? '伤口感染' : '受寒虚弱'}，已建立治疗计划，计划用品可生效。`); } else events.push(`诊所评估：${NAMES[id]}没有需要建立计划的病情。`); }
    if (a.needs === 'paint') { const paint = s.items.find((x) => x.itemId === 'paint' && x.container === id); if (paint) consumeUse(s, paint.uid); s.flags.wallPermit = false; }
    if (a.wishExact) for (const m of t.participants) fulfillWish(s, m, a.wishExact, 'exact', events);
    if (a.wishPartial) for (const m of t.participants) fulfillWish(s, m, a.wishPartial, 'partial', events);
    if (a.talk) { for (const m of t.participants) { fulfillWish(s, m, 'xuan_understood', 'exact', events); fulfillWish(s, m, 'fan_seen', 'partial', events); fulfillWish(s, m, 'adult_connection', 'partial', events); } s.daily.talked = true; }
    if (a.equip?.includes('camera')) fulfillWish(s, id, 'fan_camera', 'exact', events);
    if (a.gamble) {
      s.daily.bets++;
      const win = cardOutcome(id, rng(s.seed, `cards:${T}:${id}`), R());
      s.cash += win; income += win; s.flags.gambles = (s.flags.gambles || 0) + 1;
      events.push(`${NAMES[id]}「${a.name}」返还${win}（含本金），本次净${win - 10}。`);
    }
    for (const m of t.participants) {
      if (a.rescue && m === t.target) continue;
      const p = s.actors[m];
      if (input.actors[m].life !== 'active') continue;
      p.energy = clamp(p.energy - energyCost(input, m, a) + (a.energyGain || 0));
      p.warmth = clamp(p.warmth + (a.warm || 0));
      if (a.hygiene && !a.wash) p.hygiene = clamp(p.hygiene + a.hygiene);
      p.health = clamp(p.health + (a.heal || 0));
      if (a.intox) p.intox = Math.min(2, p.intox + a.intox);
      if (a.work && !a.eventOnly) { if (t.id === 'run') s.flags.runs = (s.flags.runs || 0) + 1; if (t.id === 'repair') s.flags.repairs = (s.flags.repairs || 0) + 1; if (['table', 'edit', 'coop', 'trio', 'shoot'].includes(t.id)) s.flags.fixedJobs = (s.flags.fixedJobs || 0) + 1; }
      if (t.id === 'oddjob' && m === 'ma') s.flags.runs = (s.flags.runs || 0) + 1;
      if (t.id === 'run' && (s.flags.runs || 0) % 3 === 0) relation(s, 'reg_chen').trust = clamp(relation(s, 'reg_chen').trust + 1, 0, 5);
      if (t.id === 'kitchen') relation(s, 'reg_liu').trust = clamp(relation(s, 'reg_liu').trust + 1, 0, 5);
      if (['scavenge', 'repair'].includes(t.id) && (s.daily.orders[t.id] || 0) === 0) relation(s, 'reg_lu').trust = clamp(relation(s, 'reg_lu').trust + (rng(s.seed, 'lu:' + T) < 0.4 ? 1 : 0), 0, 5);
      if (['graffiti', 'interview'].includes(t.id)) relation(s, 'reg_xu').trust = clamp(relation(s, 'reg_xu').trust + 1, 0, 5);
      if (['warm', 'wash'].includes(t.id) && rng(s.seed, 'wang:' + T + m) < 0.35) relation(s, 'reg_wang').trust = clamp(relation(s, 'reg_wang').trust + 1, 0, 5);
      if (a.injury) { let hit = a.injury[0] + Math.floor(rng(s.seed, `injury:${T}:${m}`) * (a.injury[1] - a.injury[0] + 1)); if (m === 'ma') hit = Math.ceil(hit * 0.75); damage[m] = hit; p.exposure.wound = true; events.push(NAMES[m] + '危险劳动事故伤害' + hit + '，留下伤口。'); }
      if (a.work && !['camp', 'service'].includes(t.zone) && !s.daily.misfortune.includes(m) && T > 3) {
        s.daily.misfortune.push(m);
        if (rng(s.seed, `misfortune:${day}:${m}`) < (m === 'ma' ? 0.25 : 0.12)) { p.energy = clamp(p.energy - 4); p.hygiene = clamp(p.hygiene - 3); events.push(NAMES[m] + '遇到小倒霉：' + misfortuneLine(s, `mis:${day}:${m}`) + '，多花体力4、卫生3。'); }
      }
      if (t.care && m === id) {
        const it = findItem(s, t.care.itemUid);
        const d = p.diseases.find((x) => x.uid === t.care.diseaseUid);
        if (it && d && consumeUse(s, it.uid)) {
          if (t.care.support) d.supportUntil = T + 1; else if (t.care.relief) d.reliefUntil = T + 1; else { cared[m] = cared[m] || new Set(); cared[m].add(d.uid); }
          p.exposure.cared = true; if (d.kind === 'wound') p.exposure.woundCovered = true;
          events.push(`${NAMES[m]}完成了一次护理（${indexById(getData().items)[it.itemId].name}）。`);
        }
      }
    }
  }
  for (const id of startAlive) {
    const before = input.actors[id].location;
    const to = zones[id] || (s.actors[id].life === 'downed' ? before : before);
    if (s.actors[id].life === 'active' || s.actors[id].life === 'downed') s.actors[id].location = zones[id] === 'pick' ? before : (zones[id] || before);
    if (before !== s.actors[id].location) moves.push({ actorId: id, from: before, to: s.actors[id].location });
  }
  settleReserved(s, zones, events);
  s.daily.orders = check.counts; s.turn = T;
  // 吃饭与环境
  for (const id of startAlive) s.actors[id].food = clamp(s.actors[id].food - 12);
  if (slot === 1 || slot === 3) {
    for (const id of [...startAlive].sort((a, b) => s.actors[a].food - s.actors[b].food)) {
      const got = eatOne(s, id);
      if (got) { s.actors[id].food = clamp(s.actors[id].food + FOOD_VALUE[got]); if (got === 'hot_soup') fulfillWish(s, id, 'good_meal', 'exact', events); }
      else events.push(NAMES[id] + '缺一份饭。');
    }
  }
  for (const id of startAlive) {
    const p = s.actors[id];
    if (p.life !== 'active') continue;
    const zone = zones[id];
    const sheltered = indoor[id] || (zone === 'camp' && s.camp.rain >= 2);
    if (!sheltered) p.warmth = clamp(p.warmth - wx.out - (p.clothes.wet ? 6 : 0));
    const hunger = p.food <= 15 ? 6 : 0, cold = p.warmth <= 20 ? 6 : 0;
    const { pressure, breakdown } = tickWishes(s, id);
    const crisisDamage = mentalTick(s, id, pressure, mindGain[id] || 0, events);
    if (breakdown.length) events.push(`${NAMES[id]}愿望压力：${breakdown.map((b) => getData().wishTemplates.find((t) => t.id === b.templateId).name + '-' + b.loss).join('、')}（本格合计-${pressure}）。`);
    const dDamage = progressDiseases(s, id, { dirty: p.hygiene < 25 || dirtyWork[id], rested: rested[id], warmPlace: sheltered, cared: cared[id] }, events);
    const reasons = [];
    if (damage[id]) reasons.push('危险劳动');
    if (hunger) reasons.push('饥饿');
    if (cold) reasons.push('失温');
    if (crisisDamage) reasons.push('精神崩溃');
    if (dDamage) reasons.push('病情');
    const protect = p.careProtect;
    p.careProtect = false;
    if (!protect) p.health = clamp(p.health - (damage[id] || 0) - hunger - cold);
    if (reasons.length && (hunger || cold || damage[id])) events.push(`${NAMES[id]}受到${reasons.join('+')}伤害。`);
    setDowned(s, id, T, reasons.join('+') || '重伤', events);
  }
  for (const id of startAlive) { const p = s.actors[id]; if (p.life === 'downed' && p.deadline <= T) kill(s, id, T, events); }
  s.ledger.income += income; s.ledger.expense += expense;
  const actions = check.jobs.map((j) => j.task.participants.map((id) => NAMES[id]).join('+') + '「' + j.action.name + '」').join('；');
  s.log.unshift(`第${day}天${SLOTS[slot]}（回合${T}）：${actions}。收入${income}，支出${expense}。`);
  let night = null;
  if (slot === 3) night = settleNight(s, day, wx, events);
  if (s.metMa && alive(s).length === 0) s.phase = 'gameover';
  else if (T === 3 && !s.metMa) s.phase = 'meeting';
  else if (day === 100 && slot === 3) s.phase = alive(s).some((id) => s.actors[id].life === 'downed') ? 'tail' : 'ending';
  if (['gameover', 'ending'].includes(s.phase)) { cleanupFuture(s, slot + 1); s.ending = computeEnding(s); }
  else if (s.phase === 'tail') { s.tailTurns = 0; for (const id of IDS) s.plan[id] = [0, 1, 2, 3].map(() => (s.actors[id].life === 'downed' ? task('wait', [id]) : s.actors[id].life === 'active' ? task('rest', [id]) : null)); s.slot = 0; events.push('第100天末夜有人濒死：进入救援尾声，最多两个回合，只处理救援。'); }
  else if (slot === 3) startNewDay(s, events);
  else { s.slot++; cleanupFuture(s, s.slot); }
  if (s.phase === 'planning') directorTick(s, events);
  for (const m of events) s.log.unshift(m);
  s.log = s.log.slice(0, 120);
  s.stateRevision += 1;
  s.lastTx = `${s.seed}:${T}`;
  s.effectiveFood = foodEquivalent(s);
  s.weatherKind = weatherOf(s.seed, s.day).kind;
  return { state: s, events, night, moves, arrivals, txId: s.lastTx };
}

function settleNight(s, day, wx, events) {
  const need = alive(s);
  const spot = s.flags.nightSpot === 'station' ? 'station' : (s.flags.shelterDay === day || s.flags.nightSpot === 'shelter') ? 'shelter' : 'camp';
  const shelter = spot === 'shelter';
  const bedUsers = shelter ? need.slice() : spot === 'station' ? [] : s.camp.bedPriority.filter((id) => need.includes(id)).slice(0, s.camp.beds);
  if (spot === 'station') events.push('今晚全员在候车室过夜。');
  nightScripted(s, events);
  for (const id of need) {
    const p = s.actors[id];
    p.food = clamp(p.food - 12);
    if (p.life === 'active') {
      const dryBed = bedUsers.includes(id);
      const blanket = s.items.find((x) => x.itemId === 'blanket' && !x.wet && (x.container === id || x.container === 'camp'));
      let recovery = (dryBed ? 50 : 25) - p.intox * 10 - (p.coffeeNight ? 10 : 0) + (blanket ? 5 : 0);
      p.energy = clamp(p.energy + recovery);
      p.mind = clamp(p.mind + (dryBed ? 5 : 2) - (shelter ? 1 : 0));
      if (shelter) p.warmth = clamp(p.warmth + 10);
      else if (spot === 'station') { p.warmth = clamp(p.warmth - Math.ceil(wx.night / 2) + (blanket ? 6 : 0)); p.mind = clamp(p.mind - 2); p.hygiene = clamp(p.hygiene - 2); if (rng(s.seed, `evict:${day}:${id}`) < 0.3) { p.mind = clamp(p.mind - 3); p.energy = clamp(p.energy - 5); events.push(NAMES[id] + '半夜被保安赶出候车室，精神-3、体力-5。'); } }
      else if (dryBed && s.camp.rain >= 2) p.warmth = clamp(p.warmth + 8 + (blanket ? 6 : 0));
      else p.warmth = clamp(p.warmth - wx.night - (p.clothes.wet ? 6 : 0) + (blanket ? 6 : 0));
      if (!dryBed && spot === 'camp') events.push(NAMES[id] + '没有干燥床位，夜间恢复较少。');
      if (p.food > 15 && p.warmth > 20) p.health = clamp(p.health + 2);
      const hunger = p.food <= 15 ? 6 : 0, cold = p.warmth <= 20 ? 6 : 0;
      if (!p.careProtect) p.health = clamp(p.health - hunger - cold);
      p.careProtect = false;
      if (cold && !dryBed && !p.diseases.some((d) => d.kind === 'chill') && rng(s.seed, `chill:${day}:${id}`) < 0.4) addDisease(s, id, 'chill', 15, '夜里冻着了', events);
      for (const d of p.diseases) if (dryBed && d.severity < 30) d.severity = Math.max(1, d.severity - R().disease.safeSleepMildSeverityReduction);
      p.hygiene = clamp(p.hygiene - 4 - (s.camp.dirt >= 60 ? 2 : 0) - (p.clothes.dirty ? 2 : 0));
      p.clothes.dirtyDays += 1;
      if (p.clothes.dirtyDays >= 3) p.clothes.dirty = true;
      if (p.clothes.wet && (dryBed || shelter) && !['rain', 'storm'].includes(wx.kind)) p.clothes.wet = false;
      nightExposure(s, id, events);
      setDowned(s, id, s.turn, '夜间饥寒', events);
      p.location = shelter ? 'service' : spot === 'station' ? 'station' : 'camp';
    }
    p.intox = 0; p.smokes = 0; p.jokeUsed = false; p.coffeeNight = false; p.grief = Math.max(0, p.grief - 1);
  }
  for (const it of s.items) if (it.wet && it.container === 'camp' && !['rain', 'storm'].includes(wx.kind)) it.wet = false;
  s.camp.dirt = clamp(s.camp.dirt + 3 + (spot === 'camp' ? need.length : 0));
  delete s.flags.nightSpot;
  return { day, ...s.ledger, end: s.cash, food: foodEquivalent(s), survivors: need.length, beds: s.camp.beds, shelter, spot };
}

function startNewDay(s, events) {
  s.day++; s.slot = 0; s.daily = freshDaily(); s.ledger = { start: s.cash, income: 0, expense: 0 };
  const dropped = discardExpired(s);
  if (dropped) events.push(`${dropped}份食物过期丢弃。`);
  restockMorning(s);
  generateMorningWishes(s, events);
  s.plan = nextPlan(s);
  s.pendingMorning = morningNode(s);
  cleanupFuture(s, 0);
  const wx = weatherOf(s.seed, s.day);
  events.push(`第${s.day}天：${wx.label}，${wx.temp}°C。`);
}

// 尾声：T401—402 只处理救援，不发工资、不吃饭、不生成事件。
function settleTail(input) {
  const check = preflight(input);
  if (check.error) return { state: input, error: check.error };
  const s = copy(input), events = [], T = s.turn + 1;
  let expense = 0;
  for (const j of check.jobs) {
    const { actor: id, task: t, action: a } = j;
    if (a.aid) { if (j.useVoucher) s.vouchers--; else { if (s.cash < R().rescue.serviceCost) { events.push(NAMES[id] + '联系救助失败：现金不足20。'); continue; } s.cash -= R().rescue.serviceCost; expense += R().rescue.serviceCost; } recover(s, id, events); }
    else if (a.rescue) { if (s.cash < 12) { events.push('陪同送援失败：现金不足12。'); continue; } s.cash -= 12; expense += 12; recover(s, t.target, events); }
  }
  for (const id of alive(s)) { const p = s.actors[id]; if (p.life === 'downed' && p.deadline <= T) kill(s, id, T, events); }
  s.turn = T; s.tailTurns += 1; s.ledger.expense += expense;
  if (!alive(s).some((id) => s.actors[id].life === 'downed') || T >= R().rescue.tailMaxGlobalTurn) { s.phase = alive(s).length ? 'ending' : 'gameover'; s.ending = computeEnding(s); }
  else { for (const id of IDS) s.plan[id] = [0, 1, 2, 3].map(() => (s.actors[id].life === 'downed' ? task('wait', [id]) : s.actors[id].life === 'active' ? task('rest', [id]) : null)); }
  s.log.unshift(`救援尾声回合${T}：${events.join('') || '没有变化。'}`);
  for (const m of events) s.log.unshift(m);
  s.stateRevision += 1;
  return { state: s, events, night: null, moves: [], arrivals: [], txId: `${s.seed}:${T}` };
}

