// 刮刮乐票面：购买时按锁定的总返还生成合法票面，展示奖金之和必须等于锁定结果。
// 三款票面共用 5 元奖表：street（对号码）、bells（三个铃铛）、goodday（好日子直揭金额）。
import { rng, pick, intBetween } from './rng.js';

export const STYLES = {
  street: { name: '街角即开彩', rule: '我的号码与中奖号码相同，即得该号码下方奖金', color: '#c0392b' },
  bells: { name: '三个铃铛', rule: '同一行三个图案相同，即得该行右侧奖金', color: '#8e6b2e' },
  goodday: { name: '好日子', rule: '刮出金额即可获得，所有中奖格相加', color: '#2f6f8f' },
};
const SYMBOLS = ['铃铛', '杯子', '面包', '雨伞', '钥匙', '袜子'];
const AMOUNTS = [5, 10, 25, 100];

// 把总返还拆成 1—3 个合法奖金位（每位取自奖表金额）。
function splitPayout(r, payout) {
  if (payout === 0) return [];
  if (payout === 5 || payout === 100) return [payout];
  if (payout === 10) return r < 0.5 ? [10] : [5, 5];
  if (payout === 25) return r < 0.4 ? [25] : r < 0.7 ? [10, 10, 5] : [5, 10, 10];
  return [payout];
}

function styleFor(seed, ticketId) {
  const keys = Object.keys(STYLES);
  return keys[Math.floor(rng(seed, 'style:' + ticketId) * keys.length)];
}

export function generateFace(seed, ticket, forcedStyle = null) {
  const style = forcedStyle || ticket.style || styleFor(seed, ticket.ticketId);
  const key = 'face:' + ticket.ticketId;
  const wins = splitPayout(rng(seed, key + ':split'), ticket.payout);
  let face;
  if (style === 'street') face = streetFace(seed, key, wins);
  else if (style === 'bells') face = bellsFace(seed, key, wins);
  else face = goodDayFace(seed, key, wins);
  face.style = style;
  face.total = ticket.payout;
  if (verifyFace(face) !== ticket.payout) throw new Error('票面奖金与锁定结果不一致 ' + ticket.ticketId);
  return face;
}

// 街角即开彩：1 个奖号，6 个号码位；命中位的号码等于奖号。
function streetFace(seed, key, wins) {
  const winning = intBetween(rng(seed, key + ':win'), 10, 39);
  const cells = [];
  const used = new Set([winning]);
  for (let i = 0; i < 6; i++) {
    if (i < wins.length) { cells.push({ n: winning, prize: wins[i], hit: true }); continue; }
    let n;
    let attempt = 0;
    do { n = intBetween(rng(seed, key + ':n' + i + ':' + attempt), 10, 39); attempt += 1; } while (used.has(n));
    used.add(n);
    cells.push({ n, prize: pick(rng(seed, key + ':p' + i), AMOUNTS), hit: false });
  }
  // 打乱顺序，命中位不总在前面。
  const order = cells.map((c, i) => ({ c, k: rng(seed, key + ':o' + i) })).sort((a, b) => a.k - b.k).map((x) => x.c);
  return { winning, cells: order };
}

// 三个铃铛：4 行，每行 3 个图案 + 1 个奖金；命中行三个相同。
function bellsFace(seed, key, wins) {
  const rows = [];
  for (let i = 0; i < 4; i++) {
    if (i < wins.length) {
      const sym = pick(rng(seed, key + ':sym' + i), SYMBOLS);
      rows.push({ syms: [sym, sym, sym], prize: wins[i], hit: true });
      continue;
    }
    // 非命中行保证不是三同。
    const a = pick(rng(seed, key + ':a' + i), SYMBOLS);
    let b = pick(rng(seed, key + ':b' + i), SYMBOLS);
    let c = pick(rng(seed, key + ':c' + i), SYMBOLS);
    if (a === b && b === c) c = SYMBOLS[(SYMBOLS.indexOf(c) + 1) % SYMBOLS.length];
    rows.push({ syms: [a, b, c], prize: pick(rng(seed, key + ':p' + i), AMOUNTS), hit: false });
  }
  const order = rows.map((r, i) => ({ r, k: rng(seed, key + ':o' + i) })).sort((x, y) => x.k - y.k).map((x) => x.r);
  return { rows: order };
}

// 好日子：3×4 方格，命中格直接是金额，其余是生活图案。
function goodDayFace(seed, key, wins) {
  const cells = [];
  for (let i = 0; i < 12; i++) {
    if (i < wins.length) cells.push({ prize: wins[i], hit: true, icon: null });
    else cells.push({ prize: 0, hit: false, icon: pick(rng(seed, key + ':i' + i), SYMBOLS) });
  }
  const order = cells.map((c, i) => ({ c, k: rng(seed, key + ':o' + i) })).sort((a, b) => a.k - b.k).map((x) => x.c);
  return { cells: order };
}

// 由票面重新验算总奖金：判定规则与展示规则一致。
export function verifyFace(face) {
  if (face.style === 'street') return face.cells.reduce((a, c) => a + (c.n === face.winning ? c.prize : 0), 0);
  if (face.style === 'bells') return face.rows.reduce((a, r) => a + (r.syms[0] === r.syms[1] && r.syms[1] === r.syms[2] ? r.prize : 0), 0);
  return face.cells.reduce((a, c) => a + (c.hit ? c.prize : 0), 0);
}

export function faceCellCount(face) {
  if (face.style === 'street') return face.cells.length + 1;
  if (face.style === 'bells') return face.rows.length;
  return face.cells.length;
}

public/game/wishes.js:
// 愿望系统：由清晨与特定事件生成，每个行动回合增长，超阈值扣精神，满足/替代/延期/拒绝四种回应。
import { getData } from './data.js';
import { rng, pick } from './rng.js';
import { clamp, wishMindLoss, wishPressure } from './rules.js';

export const GROWTH = { daily: 2, comfort: 1, personal: 1, relational: 1, aspiration: 0.5 };
// 各类愿望从第几天开始出现：前几天先学会活着。
const UNLOCK_DAY = { daily: 2, comfort: 5, personal: 9, relational: 14, aspiration: 21 };
const COOLDOWN_DAYS = 6;

export function activeWishes(state, actorId) {
  return state.wishes.filter((w) => w.actor === actorId && w.status === 'active');
}

export function templateOf(w) {
  return getData().wishTemplates.find((t) => t.id === w.templateId);
}

function newWish(state, actorId, tpl) {
  state.wishSeq = (state.wishSeq || 0) + 1;
  const grace = getData().rules.desire.latentRevealGraceTurns;
  const w = {
    uid: 'w' + state.wishSeq,
    templateId: tpl.id,
    actor: actorId,
    category: tpl.category,
    intensity: tpl.startIntensity,
    createdTurn: state.turn,
    createdDay: state.day,
    revealed: false,
    revealTurn: state.turn + grace,
    promise: null,
    declined: false,
    status: 'active',
    lastLoss: 0,
  };
  state.wishes.push(w);
  return w;
}

function eligibleTemplates(state, actorId) {
  const active = activeWishes(state, actorId);
  const cats = new Set(active.map((w) => w.category));
  const recent = new Set(
    state.wishes.filter((w) => w.actor === actorId && w.status !== 'active' && state.day - (w.closedDay || 0) < COOLDOWN_DAYS).map((w) => w.templateId),
  );
  return getData().wishTemplates.filter(
    (t) => (t.actorScope === 'all' || t.actorScope === actorId) && !cats.has(t.category) && state.day >= UNLOCK_DAY[t.category] && !recent.has(t.id),
  );
}

// 清晨生成：每人最多 3 个活动愿望。D9 保证每人一个个人愿望（第一次暗示教学）。
export function generateMorningWishes(state, events) {
  const rules = getData().rules.desire;
  for (const id of Object.keys(state.actors)) {
    const p = state.actors[id];
    if (p.life !== 'active') continue;
    if (activeWishes(state, id).length >= rules.maxActivePerActor) continue;
    const pool = eligibleTemplates(state, id);
    if (!pool.length) continue;
    let tpl = null;
    if (state.day === 9) {
      tpl = pool.find((t) => t.category === 'personal' && t.actorScope === id) || null;
    }
    if (!tpl) {
      const r = rng(state.seed, 'wish:' + state.day + ':' + id);
      const chance = state.day <= 3 ? 0.55 : 0.32;
      if (r > chance) continue;
      // 马哥对牌与彩票的念头更常冒出来。
      const weighted = pool.flatMap((t) => (id === 'ma' && (t.id === 'ma_cards' || t.id === 'ma_lottery') ? [t, t] : [t]));
      tpl = pick(rng(state.seed, 'wishpick:' + state.day + ':' + id), weighted);
    }
    if (!tpl) continue;
    newWish(state, id, tpl);
    events.push(`${state.names[id]}有了新念头（尚未说出口）。`);
  }
}

// 事件触发的愿望（如站口牌桌让马哥想坐一次）。已有同类则只加强度。
export function nudgeWish(state, actorId, templateId, amount = 10) {
  const existing = activeWishes(state, actorId).find((w) => w.templateId === templateId);
  if (existing) {
    existing.intensity = clamp(existing.intensity + amount);
    return existing;
  }
  const tpl = getData().wishTemplates.find((t) => t.id === templateId);
  if (!tpl) return null;
  if (activeWishes(state, actorId).some((w) => w.category === tpl.category)) return null;
  if (activeWishes(state, actorId).length >= getData().rules.desire.maxActivePerActor) return null;
  const w = newWish(state, actorId, tpl);
  w.intensity = clamp(w.intensity + amount);
  return w;
}

// 一个行动回合：增长、揭示、算压力。返回 {pressure, breakdown}
export function tickWishes(state, actorId) {
  const rules = getData().rules;
  const list = activeWishes(state, actorId);
  const pressed = [];
  for (const w of list) {
    if (!w.revealed && state.turn >= w.revealTurn) w.revealed = true;
    const promised = w.promise && state.turn < w.promise.until;
    if (promised) { w.lastLoss = 0; continue; }
    w.intensity = clamp(w.intensity + GROWTH[w.category]);
    if (w.promise && state.turn >= w.promise.until && !w.promise.expiredNoted) {
      w.promise.expiredNoted = true;
      w.intensity = clamp(w.intensity + 8);
    }
    if (!w.revealed) { w.lastLoss = 0; continue; }
    w.lastLoss = wishMindLoss(w.intensity, rules);
    if (w.lastLoss > 0) pressed.push(w);
  }
  const pressure = wishPressure(pressed.map((w) => w.intensity), rules);
  return { pressure, breakdown: pressed.map((w) => ({ uid: w.uid, templateId: w.templateId, loss: w.lastLoss })) };
}

// 满足：exact 减 70，partial 减 30；归零即关闭。
export function fulfillWish(state, actorId, templateId, mode, events) {
  const w = activeWishes(state, actorId).find((x) => x.templateId === templateId);
  if (!w) return null;
  const d = getData().rules.desire;
  const cut = mode === 'exact' ? d.exactFulfillmentIntensityReduction : d.partialFulfillmentIntensityReduction;
  w.intensity = clamp(w.intensity - cut);
  w.revealed = true;
  w.promise = null;
  const tpl = templateOf(w);
  if (mode === 'exact' || w.intensity <= 0) {
    w.status = 'fulfilled';
    w.closedDay = state.day;
    if (events) events.push(`${state.names[actorId]}的愿望「${tpl.name}」得到了回应。`);
  } else if (events) {
    events.push(`${state.names[actorId]}的「${tpl.name}」得到部分缓解（强度-${cut}）。`);
  }
  return w;
}

// 玩家回应：promise（4 回合缓冲，最多一次）、decline（一次轻微失落，愿望仍在）。
export function respondWish(state, uid, response) {
  const w = state.wishes.find((x) => x.uid === uid && x.status === 'active');
  if (!w) return { error: '没有这条愿望' };
  const d = getData().rules.desire;
  if (response === 'promise') {
    if (w.promise && w.promise.extensions >= d.promiseExtensionsMax) return { error: '同一愿望只能延期一次，不能靠一直说“明天”冻结它' };
    w.promise = { until: state.turn + d.promisedGraceTurns, extensions: (w.promise?.extensions || 0) + 1, madeTurn: state.turn };
    w.revealed = true;
    return { ok: true, message: '已约定：' + d.promisedGraceTurns + '回合内不再积压，到期未兑现会更失望。' };
  }
  if (response === 'decline') {
    if (w.declined) return { error: '已经明确拒绝过了，不重复扣精神；长期不给替代仍会积压。' };
    w.declined = true;
    w.revealed = true;
    const p = state.actors[w.actor];
    p.mind = clamp(p.mind - 2);
    return { ok: true, message: '说清楚了。' + state.names[w.actor] + '有点失落（精神-2），但知道了答案。' };
  }
  return { error: '未知回应' };
}

export function wishSummary(state, actorId) {
  return activeWishes(state, actorId)
    .filter((w) => w.revealed)
    .sort((a, b) => b.intensity - a.intensity)
    .map((w) => ({ ...w, tpl: templateOf(w) }));
}
